+    storagePath,
+    log: recordingLog([]),
+    temporaryPath: () => {
+      temporaryWrites += 1;
+
+      return temporaryWrites === 1 ? olderTemporary : newerTemporary;
+    },
+  });
+  writer.record(DEVICE_ID, ANCHOR);
+
