+        contents: '{"placeholder-device":1700000000000,"placeholder-other-device":1700000898000}',
+        anchor: ANCHOR,
+        otherAnchor: OTHER_ANCHOR,
+      },
+    );
+  } finally {
+    releaseOlderRename();
+    t.mock.restoreAll();
+    syncBuiltinESMExports();
+  }
+});
